// Looks up a doctor's letterhead credentials by name. Matches loosely (by
// surname/keyword) instead of requiring an exact string, so renaming a
// doctor slightly in Settings (e.g. dropping "Mrs."/"Dr.") doesn't silently
// break the credential block on printed prescriptions.
function getDoctorProfile(doctorName) {
  if (!doctorName) return null;
  const n = doctorName.toLowerCase();
  if (n.includes("smitha")) return DOCTOR_PROFILES["Mrs. Smitha Sunil"];
  if (n.includes("sunil")) return DOCTOR_PROFILES["Dr. Sunil R."];
  return DOCTOR_PROFILES[doctorName] || null;
}

const todayStr = () => {
  const d = new Date();
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, "0");
  const day = String(d.getDate()).padStart(2, "0");
  return `${y}-${m}-${day}`;
};
const fmtDate = (d) => {
  if (!d) return "—";
  const dt = new Date(d + "T00:00:00");
  return dt.toLocaleDateString("en-IN", { day: "2-digit", month: "short", year: "numeric" });
};
const fmtTime12 = (t) => {
  if (!t) return "";
  const [h, m] = t.split(":").map(Number);
  const period = h >= 12 ? "PM" : "AM";
  const h12 = h % 12 === 0 ? 12 : h % 12;
  return `${h12}:${String(m).padStart(2, "0")} ${period}`;
};
const fmtINR = (n) => {
  const num = Number(n) || 0;
  return "₹" + num.toLocaleString("en-IN", { maximumFractionDigits: 0 });
};

// Inline-style colors for pill/tab/toggle buttons. Using inline styles here
// (instead of Tailwind's arbitrary-value classes like bg-[#123C6D]) avoids a
// rendering quirk in some preview contexts where certain arbitrary color
// utility classes don't paint, leaving text invisible against no background.
function pillStyle(active, activeColor = "#123C6D") {
  return active
    ? { background: activeColor, color: "#ffffff", borderColor: activeColor }
    : { background: "#ffffff", color: "#33475B", borderColor: "#C9DDF0" };
}

