async function shareOrCopy(title, text, flash) {
  if (navigator.share) {
    try {
      await navigator.share({ title, text });
      return;
    } catch (e) {
      if (e && e.name === "AbortError") return; // user cancelled the share sheet
    }
  }
  try {
    await navigator.clipboard.writeText(text);
    flash("Copied to clipboard — paste into WhatsApp, SMS, or email");
  } catch {
    flash("Couldn't share automatically — use Print instead");
  }
}

