const inputCls = "w-full px-3 py-2.5 rounded-lg border border-[#C9DDF0] bg-[#F4F8FC] text-[#16283D] text-sm focus:outline-none focus:ring-2 focus:ring-[#123C6D]/30 focus:border-[#123C6D] transition";

/* Medicine name autocomplete input */
function MedicineAutocomplete({ value, onChange, medicineList }) {
  const [open, setOpen] = useState(false);
  const [query, setQuery] = useState(value || "");
  const boxRef = useRef(null);

  useEffect(() => setQuery(value || ""), [value]);

  useEffect(() => {
    function onDocClick(e) {
      if (boxRef.current && !boxRef.current.contains(e.target)) setOpen(false);
    }
    document.addEventListener("mousedown", onDocClick);
    return () => document.removeEventListener("mousedown", onDocClick);
  }, []);

  const list = medicineList || DEFAULT_MEDICINES;
  const suggestions = useMemo(() => {
    if (!query.trim()) return [];
    const q = query.toLowerCase();
    return list.filter((m) => m.toLowerCase().includes(q)).slice(0, 8);
  }, [query, list]);

  return (
    <div className="relative" ref={boxRef}>
      <input
        className={inputCls}
        placeholder="Start typing e.g. Paracetamol..."
        value={query}
        onChange={(e) => { setQuery(e.target.value); onChange(e.target.value); setOpen(true); }}
        onFocus={() => setOpen(true)}
      />
      {open && suggestions.length > 0 && (
        <div className="absolute z-20 mt-1 w-full bg-white border border-[#C9DDF0] rounded-lg shadow-lg overflow-hidden max-h-56 overflow-y-auto">
          {suggestions.map((s) => (
            <button
              type="button"
              key={s}
              className="w-full text-left px-3 py-2 text-sm hover:bg-[#EAF3FB] text-[#16283D] flex items-center gap-2"
              onClick={() => { onChange(s); setQuery(s); setOpen(false); }}
            >
              <Pill size={13} className="text-[#1D6FC2] shrink-0" />
              {s}
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

function Select({ value, onChange, options, placeholder }) {
  return (
    <div className="relative">
      <select
        value={value}
        onChange={(e) => onChange(e.target.value)}
        className={inputCls + " appearance-none pr-8 cursor-pointer"}
      >
        {placeholder && <option value="">{placeholder}</option>}
        {options.map((o) => (
          <option key={o} value={o}>{o}</option>
        ))}
      </select>
      <ChevronDown size={15} className="absolute right-2.5 top-3 text-[#5A7290] pointer-events-none" />
    </div>
  );
}

