function BillModal({ patients, doctors, presetPatient, editBill, onClose, onSave }) {
  const [patientQuery, setPatientQuery] = useState("");
  const [showList, setShowList] = useState(false);
  const [patientId, setPatientId] = useState(editBill?.patientId || presetPatient?.id || "");
  const [patientName, setPatientName] = useState(editBill?.patientName || presetPatient?.name || "");
  const [doctor, setDoctor] = useState(editBill?.doctor || doctors[0]);
  const [date, setDate] = useState(editBill?.date || todayStr());
  const [amount, setAmount] = useState(editBill?.amount ? String(editBill.amount) : "");
  const [mode, setMode] = useState(editBill?.mode || PAYMENT_MODES[0]);
  const [notes, setNotes] = useState(editBill?.notes || "");

  const matches = patients.filter((p) => p.name.toLowerCase().includes(patientQuery.toLowerCase())).slice(0, 6);
  const canSave = patientName.trim() && Number(amount) > 0;

  const handleSave = () => {
    onSave({ id: editBill?.id, patientId, patientName, doctor, date, amount: Number(amount), mode, notes });
  };

  return (
    <Modal title={editBill ? "Edit Bill" : "Generate Bill"} onClose={onClose}>
      <Field label="Patient" required>
        <div className="relative">
          <input
            className={inputCls}
            value={patientQuery || patientName}
            onChange={(e) => { setPatientQuery(e.target.value); setPatientName(e.target.value); setPatientId(""); setShowList(true); }}
            onFocus={() => setShowList(true)}
            placeholder="Search patient by name"
          />
          {showList && patientQuery && (
            <div className="absolute z-20 mt-1 w-full bg-white border border-[#C9DDF0] rounded-lg shadow-lg max-h-52 overflow-y-auto">
              {matches.map((p) => (
                <button type="button" key={p.id} className="w-full text-left px-3 py-2 text-sm hover:bg-[#EAF3FB] flex justify-between"
                  onClick={() => { setPatientId(p.id); setPatientName(p.name); setPatientQuery(""); setShowList(false); }}>
                  <span>{p.name}</span><span className="text-xs text-[#5A7290]">{p.phone}</span>
                </button>
              ))}
              {matches.length === 0 && <div className="px-3 py-2 text-sm text-[#5A7290]">No matching patient. Add them from the Patients tab first.</div>}
            </div>
          )}
        </div>
      </Field>

      <div className="grid sm:grid-cols-2 gap-x-4">
        <Field label="Doctor Consulted" required><Select value={doctor} onChange={setDoctor} options={doctors} /></Field>
        <Field label="Date" required><input type="date" className={inputCls} value={date} onChange={(e) => setDate(e.target.value)} /></Field>
        <Field label="Amount (₹)" required>
          <div className="relative">
            <IndianRupee size={14} className="absolute left-3 top-3 text-[#5A7290]" />
            <input type="number" min="0" className={inputCls + " pl-8"} value={amount} onChange={(e) => setAmount(e.target.value)} placeholder="e.g. 500" />
          </div>
        </Field>
        <Field label="Payment Mode" required><Select value={mode} onChange={setMode} options={PAYMENT_MODES} /></Field>
      </div>

      <Field label="Notes (optional)">
        <input className={inputCls} value={notes} onChange={(e) => setNotes(e.target.value)} placeholder="e.g. Consultation + dressing" />
      </Field>

      <div className="flex justify-end gap-2 mt-2">
        <button onClick={onClose} className="btn-ghost2">Cancel</button>
        <button disabled={!canSave} onClick={handleSave} className="btn-primary2 disabled:opacity-40"><Save size={14}/> {editBill ? "Save Changes" : "Generate Bill"}</button>
      </div>
      <style>{`
        .btn-primary2 { display:flex; align-items:center; gap:6px; background:#123C6D; color:white; padding:9px 16px; border-radius:10px; font-size:13px; font-weight:600; }
        .btn-ghost2 { padding:9px 16px; border-radius:10px; font-size:13px; font-weight:600; color:#33475B; }
        .btn-ghost2:hover { background:#EAF3FB; }
      `}</style>
    </Modal>
  );
}

function PrescriptionsView({ prescriptions, patients, doctors, clinicName, onAdd, onDelete, onPrint, onShare }) {
  const [query, setQuery] = useState("");
  const [doctorFilter, setDoctorFilter] = useState("all");

  const sorted = [...prescriptions].sort((a, b) => b.date.localeCompare(a.date));
  const filtered = sorted
    .filter((r) => r.patientName.toLowerCase().includes(query.toLowerCase()))
    .filter((r) => doctorFilter === "all" || r.doctor === doctorFilter);

  // Group prescriptions by month, then by exact date, preserving newest-first order.
  const groups = [];
  filtered.forEach((rx) => {
    const monthKey = rx.date.slice(0, 7);
    const monthLabel = new Date(rx.date + "T00:00:00").toLocaleDateString("en-IN", { month: "long", year: "numeric" });
    let monthGroup = groups.find((g) => g.key === monthKey);
    if (!monthGroup) {
      monthGroup = { key: monthKey, label: monthLabel, days: [] };
      groups.push(monthGroup);
    }
    let dayGroup = monthGroup.days.find((d) => d.key === rx.date);
    if (!dayGroup) {
      dayGroup = { key: rx.date, label: fmtDate(rx.date), rxs: [] };
      monthGroup.days.push(dayGroup);
    }
    dayGroup.rxs.push(rx);
  });

  return (
    <div>
      <div className="flex items-center justify-between mb-6 flex-wrap gap-3">
        <h1 style={{ fontFamily: "Fraunces, serif" }} className="text-2xl font-semibold text-[#123C6D]">Prescriptions</h1>
        <button onClick={onAdd} className="btn-primary2"><Plus size={15} /> New Prescription</button>
      </div>

      <div className="flex gap-2 mb-5 flex-wrap">
        <button onClick={() => setDoctorFilter("all")} className="px-3.5 py-1.5 rounded-full text-xs font-semibold border" style={pillStyle(doctorFilter === "all")}>
          All Doctors
        </button>
        {doctors.map((d) => (
          <button key={d} onClick={() => setDoctorFilter(d)} className="px-3.5 py-1.5 rounded-full text-xs font-semibold border" style={pillStyle(doctorFilter === d)}>
            {d}
          </button>
        ))}
      </div>

      <div className="relative mb-5 max-w-sm">
        <Search size={15} className="absolute left-3 top-3 text-[#5A7290]" />
        <input className={inputCls + " pl-9"} placeholder="Search by patient name..." value={query} onChange={(e) => setQuery(e.target.value)} />
      </div>

      {filtered.length === 0 ? (
        <div className="bg-white rounded-xl border border-[#E3ECF5] p-10 text-center text-sm text-[#5A7290]">
          {prescriptions.length === 0 ? "No prescriptions yet." : "No prescriptions match your filters."}
        </div>
      ) : (
        <div className="space-y-8">
          {groups.map((monthGroup) => (
            <div key={monthGroup.key}>
              <div className="flex items-center gap-3 mb-4">
                <h2 style={{ fontFamily: "Fraunces, serif" }} className="text-lg font-semibold text-[#123C6D]">
                  {monthGroup.label}
                </h2>
                <div className="h-px flex-1 bg-[#E3ECF5]" />
                <span className="text-xs text-[#5A7290] font-medium">
                  {monthGroup.days.reduce((n, d) => n + d.rxs.length, 0)} prescription{monthGroup.days.reduce((n, d) => n + d.rxs.length, 0) === 1 ? "" : "s"}
                </span>
              </div>
              <div className="space-y-6">
                {monthGroup.days.map((dayGroup) => (
                  <div key={dayGroup.key}>
                    <div className="text-xs uppercase tracking-wide text-[#5A7290] font-semibold mb-2.5">
                      {dayGroup.label}
                    </div>
                    <div className="grid sm:grid-cols-2 gap-4">
                      {dayGroup.rxs.map((r) => (
                        <RxPad
                          key={r.id}
                          rx={r}
                          patientName={r.patientName}
                          doctorName={r.doctor}
                          clinicName={clinicName}
                          onDelete={() => onDelete(r.id)}
                          onPrint={() => onPrint(r)}
                          onShare={() => onShare(r)}
                        />
                      ))}
                    </div>
                  </div>
                ))}
              </div>
            </div>
          ))}
        </div>
      )}
      <style>{`.btn-primary2 { display:flex; align-items:center; gap:6px; background:#123C6D; color:white; padding:9px 16px; border-radius:10px; font-size:13px; font-weight:600; }`}</style>
    </div>
  );
}

